public class RomanNumerals {
    public static String intToRoman(int num) {
        List<Pair> romans = Arrays.asList(
            new Pair(1000, "M"), new Pair(900, "CM"), new Pair(500, "D"), 
            new Pair(400, "CD"), new Pair(100, "C"), new Pair(90, "XC"),
            new Pair(50, "L"), new Pair(40, "XL"), new Pair(10, "X"), 
            new Pair(9, "IX"), new Pair(5, "V"), new Pair(4, "IV"),
            new Pair(1, "I")
        );
        StringBuilder roman = new StringBuilder();
        for (Pair p : romans) {
            while (num >= p.num) {
                roman.append(p.symbol);
                num -= p.num;
            }
        }
        return roman.toString();
    }

    private static class Pair {
        final int num;
        final String symbol;

        Pair(int num, String symbol) {
            this.num = num;
            this.symbol = symbol;
        }
    }
}

intToRoman(num) {
    const romans = [
        [1000, "M"], [900, "CM"], [500, "D"],
        [400, "CD"], [100, "C"], [90, "XC"],
        [50, "L"], [40, "XL"], [10, "X"], 
        [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]
    ];
    let roman = "";
    for (const [value, symbol] of romans) {
        while (num >= value) {
            roman += symbol;
            num -= value;
        }
    }
    return roman;
}

romanToInt(string s) {
    unordered_map<char, int> roman_values = { {'I', 1}, {'V', 5}, {'X', 10}, {'L', 50}, {'C', 100}, {'D', 500}, {'M', 1000} };
    int total = 0;
    int prev_value = 0;

    for (char c : s) {
        int current_value = roman_values[c];
        if (current_value > prev_value)
            total += current_value - (2 * prev_value);
        else
            total += current_value;
        prev_value = current_value;
    }

    return total;
}

