    let result = 0;
    const st = [];

    for (let i = 0; i < n; ++i) {
        if (s[i] === '(') {
            st.push(i);
        } else {
            if (st.length > 0 && s[st[st.length - 1]] === '(') {
                st.pop();
            } else {
                st.push(i);
            }
        }
    }

    if (st.length === 0) {
        result = n;
    } else {
        let right = n, left = 0;
        while (st.length > 0) {
            left = st.pop();
            result = Math.max(result, right - left - 1);
            right = left;
        }
        result = Math.max(result, right);
    }

    return result;
}

