private void combine(int[] candidates, int target, int start, List<List<Integer>> result, List<Integer> current) {
    if (target == 0) {
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < candidates.length && target >= candidates[i]; i++) {
