    const nums = [...Array(n)].map((_, i) => i + 1);
    let result = '';

    for (let i = 1; i < n; i++) {
        factorials[i] = factorials[i - 1] * i;
    }

    k--;

    for (let i = n; i >= 1; i--) {
        const index = Math.floor(k / factorials[i - 1]);
        k %= factorials[i - 1];
        result += nums[index];
        nums.splice(index, 1);
    }

    return result;
}

