ListNode* rotateRight(ListNode* head, int k) {
    if (!head || !head->next || k == 0) return head;

    ListNode *current = head;
    int len = 1;
    while (current->next) {
        len++;
        current = current->next;
    }
    current->next = head;
    k = len - k % len;

    while (k--) {
        current = current->next;
    }
    head = current->next;
    current->next = nullptr;

    return head;
}

