def connect(root: 'Node') -> 'Node':
    if not root:
        return None

    q = [root]

    while q:
        level_size = len(q)
        prev = None

        for i in range(level_size):
            current_node = q.pop(0)

            if prev:
                prev.next = current_node
            prev = current_node

            if current_node.left:
                q.append(current_node.left)
            if current_node.right:
                q.append(current_node.right)

    return root

