    if (!head || !head->next || !head->next->next) return;

    // Find the middle node
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }

    // Reverse the second half
    ListNode* prev = nullptr;
    ListNode* curr = slow->next;
    ListNode* next;
    while (curr) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    slow->next = nullptr;

    // Merge two halves
    ListNode* first = head;
    ListNode* second = prev;
    while (second) {
        next = first->next;
        first = first->next = second;
        second = next;
    }
}

