    int start = 0, end;
    while ((end = find(s.begin() + start, s.end(), ' ') - s.begin()) < s.size()) {
        reverse(s.begin() + start, s.begin() + end);
        start = end + 1;
    }
    reverse(s.begin() + start, s.end());
}

void reverseWords(char[] s) {
    reverse(s, 0, s.length - 1);
    int start = 0;
    for (int i = 0; i <= s.length; i++) {
        if (i == s.length || s[i] == ' ') {
            reverse(s, start, i - 1);
            start = i + 1;
        }
    }
}

