public List<String> findRepeatedDnaSequences(String s) {
    List<String> result = new ArrayList<>();
    HashMap<String, Integer> dnaCounter = new HashMap<>();

    for (int i = 0; i <= s.length() - 10; i++) {
        String sequence = s.substring(i, i + 10);
        dnaCounter.put(sequence, dnaCounter.getOrDefault(sequence, 0) + 1);
        if (dnaCounter.get(sequence) == 2) {
            result.add(sequence);
        }
    }

    return result;
}

findRepeatedDnaSequences(s) {
    const dnaCounter = new Map();
    const result = [];

    for (let i = 0; i <= s.length - 10; i++) {
        const sequence = s.slice(i, i + 10);
        dnaCounter.set(sequence, (dnaCounter.get(sequence) || 0) + 1);
        if (dnaCounter.get(sequence) === 2) {
            result.push(sequence);
        }
    }

    return result;
}

