ListNode* removeElements(ListNode* head, int val) {
    ListNode** current = &head;

    while (*current != NULL) {
        if ((*current)->val == val) {
            ListNode* next = (*current)->next;
            delete *current;
            *current = next;
        } else {
            current = &(*current)->next;
        }
    }

    return head;
}

