      for (let i = current + 1; i <= 9; i++) {
        currentComb.push(i);
        helper(k - 1, n - i, i, currentComb, result);
        currentComb.pop();
      }
    }
  }

  const result = [];
  helper(k, n, 0, [], result);
  return result;
}

