public class Solution {
    public List<String> generatePalindromes(String s) {
        List<String> result = new ArrayList<>();
        Map<Character, Integer> charCount = new HashMap<>();
        for (char c : s.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        String midChar = "";
        List<Character> halfChars = new ArrayList<>();
        int numOdds = 0;
        for (Map.Entry<Character, Integer> entry : charCount.entrySet()) {
            if (entry.getValue() % 2 == 1) {
                numOdds++;
                midChar = String.valueOf(entry.getKey());
            }
            for (int i = 0; i < entry.getValue() / 2; i++) {
                halfChars.add(entry.getKey());
            }

            if (numOdds > 1) {
                return result;
            }
        }

        permute(0, halfChars, midChar, new ArrayList<>(), result);
        return result;
    }

    private void permute(int idx, List<Character> halfChars, String midChar, List<Character> current, List<String> result) {
        if (idx == halfChars.size()) {
            String firstHalf = "".valueOf(current.toArray(new Character[0]));
            result.add(firstHalf + midChar + new StringBuilder(firstHalf).reverse());
            return;
        }

        for (int i = 0; i < halfChars.size(); i++) {
            if (i > 0 && halfChars.get(i) == halfChars.get(i - 1)) {
                continue;
            }
            Character c = halfChars.remove(i);
            current.add(c);
            permute(idx + 1, halfChars, midChar, current, result);
            current.remove(current.size() - 1);
            halfChars.add(i, c);
        }
    }
}

generatePalindromes(s) {
    let result = [];
    let charCount = new Map();
    for (const c of s) {
        charCount.set(c, (charCount.get(c) || 0) + 1);
    }

    let midChar = "";
    let halfChars = [];
    let numOdds = 0;
    charCount.forEach((count, char) => {
        if (count % 2 === 1) {
            numOdds++;
            midChar = char;
        }
        for (let i = 0; i < Math.floor(count / 2); i++) {
            halfChars.push(char);
        }

        if (numOdds > 1) {
            return [];
        }
    });

    function btPerm(idx, current) {
        if (idx === halfChars.length) {
            const firstHalf = current.join('');
            result.push(firstHalf + midChar + firstHalf.split('').reverse().join(''));
            return;
        }

        for (let i = 0; i < halfChars.length; i++) {
            if (i > 0 && halfChars[i] === halfChars[i - 1]) {
                continue;
            }
            const char = halfChars.splice(i, 1)[0];
            current.push(char);
            btPerm(idx + 1, current);
            current.pop();
            halfChars.splice(i, 0, char);
        }
    }

    halfChars.sort();
    btPerm(0, []);

    return result;
}

