    const roots = new Array(m * n).fill(-1);
    const dirs = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let islandCount = 0;
    const result = [];

    const index = (x, y) => x * n + y;

    function find(x) {
        if (roots[x] !== x) roots[x] = find(roots[x]);
        return roots[x];
    }

    for (const [i, j] of positions) {
        const idx = index(i, j);
        if (roots[idx] !== -1) {
            result.push(islandCount);
