            const neighbor = index(ni, nj);
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && roots[neighbor] !== -1) {
                const root_neighbor = find(neighbor);
                if (idx !== root_neighbor) {
                    roots[root_neighbor] = idx;
                    islandCount--;
                }
            }
        }
        result.push(islandCount);
    }
