public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public List<List<Integer>> verticalOrder(TreeNode root) {
        if (root == null) return new ArrayList<>();

        HashMap<Integer, List<Integer>> columnTable = new HashMap<>();
        Queue<Pair<TreeNode, Integer>> q = new LinkedList<>();
        q.offer(new Pair<>(root, 0));

        while (!q.isEmpty()) {
            TreeNode curNode = q.peek().getKey();
            int column = q.peek().getValue();
            q.poll();

            if (curNode != null) {
                columnTable.putIfAbsent(column, new ArrayList<>());
                columnTable.get(column).add(curNode.val);
                q.offer(new Pair<>(curNode.left, column - 1));
                q.offer(new Pair<>(curNode.right, column + 1));
            }
        }

        return new ArrayList<>(columnTable.values());
    }
}

TreeNode {
    constructor(val, left, right) {
        this.val = (val===undefined ? 0 : val)
        this.left = (left===undefined ? null : left)
        this.right = (right===undefined ? null : right)
    }
}

var verticalOrder = function(root) {
    if (!root) return [];

    const columnTable = new Map();
    const q = [[root, 0]];

    while (q.length) {
        const [curNode, column] = q.shift();

        if (curNode) {
            if (!columnTable.has(column)) columnTable.set(column, []);
            columnTable.get(column).push(curNode.val);
            q.push([curNode.left, column - 1]);
            q.push([curNode.right, column + 1]);
        }
    }

    return Array.from(columnTable.entries()).sort((a, b) => a[0] - b[0]).map(entry => entry[1]);
};

