    envelopes.sort((a, b) => a[0] === b[0] ? b[1] - a[1] : a[0] - b[0]);
    const dp = [];

    for (const envelope of envelopes) {
        const idx = lowerBound(dp, envelope[1]);
        if (idx === dp.length) {
            dp.push(envelope[1]);
        } else {
            dp[idx] = envelope[1];
        }
    }

    return dp.length;

    function lowerBound(arr, target) {
        let low = 0, high = arr.length;
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

