private int maxDepth(List<NestedInteger> nestedList) {
    int depth = 1;
    for (NestedInteger nested : nestedList) {
        if (!nested.isInteger()) {
            depth = Math.max(depth, 1 + maxDepth(nested.getList()));
        }
    }
    return depth;
}

private int sumHelper(List<NestedInteger> nestedList, int depth) {
    int sum = 0;
    for (NestedInteger nested : nestedList) {
        if (nested.isInteger()) {
            sum += depth * nested.getInteger();
        } else {
            sum += sumHelper(nested.getList(), depth - 1);
        }
    }
    return sum;
}

depthSumInverse(nestedList) {
    function maxDepthHelper(nestedList) {
        let depth = 1;
        for (let nested of nestedList) {
            if (Array.isArray(nested)) {
                depth = Math.max(depth, 1 + maxDepthHelper(nested));
            }
        }
        return depth;
    }
    function sumHelper(nestedList, depth) {
        let sum = 0;
        for (let nested of nestedList) {
            if (typeof nested === "number") {
                sum += depth * nested;
            } else {
                sum += sumHelper(nested, depth - 1);
            }
        }
        return sum;
    }
    let maxDepth = maxDepthHelper(nestedList);
    return sumHelper(nestedList, maxDepth);
}

