function findLeavesHelper(node, result, level) {
    if (node === null) return -1;
    const leftLevel = findLeavesHelper(node.left, result, level + 1);
    const rightLevel = findLeavesHelper(node.right, result, level + 1);
    level = Math.max(leftLevel, rightLevel) + 1;
    if (result.length <= level) result.push([]);
    result[level].push(node.val);
    return level;
}

isPerfectSquare(int num) {
    if (num < 2) return true;
    long long left = 2, right = num / 2, mid, square;
    while (left <= right) {
        mid = left + (right - left) / 2;
        square = mid * mid;
        if (square == num) return true;
        if (square > num) right = mid - 1;
        else left = mid + 1;
    }
    return false;
}

