getMoneyAmount(int n) {
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    for (int i = n - 1; i >= 1; i--) {
        for (int j = i + 1; j <= n; j++) {
            int min_cost = INT_MAX;
            for (int k = i; k < j; k++) {
                int cost = k + max(dp[i][k - 1], dp[k + 1][j]);
                min_cost = min(min_cost, cost);
            }
            dp[i][j] = min_cost;
        }
    }
    return dp[1][n];
}

