    queue<int> released;
public:
    PhoneDirectory(int maxNumbers): available(maxNumbers, true) {}

    int get() {
        if(!released.empty()) {
            int number = released.front();
            released.pop();
            available[number] = false;
            return number;
        }
        for(int i = 0; i < available.size(); i++) {
            if(available[i]) {
                available[i] = false;
                return i;
            }
        }
        return -1;
    }

