java.util.PriorityQueue;

public int trapRainWater(int[][] heightMap) {
    int m = heightMap.length, n = heightMap[0].length;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    boolean[][] visited = new boolean[m][n];

    for (int i = 0; i < m; i++) {
        pq.offer(new int[]{heightMap[i][0], i, 0});
        pq.offer(new int[]{heightMap[i][n - 1], i, n - 1});
        visited[i][0] = visited[i][n - 1] = true;
    }

    for (int i = 1; i < n - 1; i++) {
        pq.offer(new int[]{heightMap[0][i], 0, i});
        pq.offer(new int[]{heightMap[m - 1][i], m - 1, i});
        visited[0][i] = visited[m - 1][i] = true;
    }

    int water = 0, maxHeight = 0;
    int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    while (!pq.isEmpty()) {
        int[] t = pq.poll();
        int h = t[0], r = t[1], c = t[2];
        maxHeight = Math.max(maxHeight, h);
        for (int[] dir : dirs) {
            int x = r + dir[0], y = c + dir[1];
            if (x < 0 || x >= m || y < 0 || y >= n || visited[x][y]) continue;
            if (heightMap[x][y] < maxHeight) water += maxHeight - heightMap[x][y];
            pq.offer(new int[]{heightMap[x][y], x, y});
            visited[x][y] = true;
        }
    }

    return water;
}

trapRainWater(heightMap) {
    const m = heightMap.length;
    const n = heightMap[0].length;
    const pq = [];
    const visited = Array.from({ length: m }, () => Array(n).fill(false));

    const comparator = (a, b) => a[0] - b[0];

    for (let i = 0; i < m; i++) {
        pq.push([heightMap[i][0], i, 0], [heightMap[i][n - 1], i, n - 1]);
        visited[i][0] = visited[i][n - 1] = true;
    }

    for (let i = 1; i < n - 1; i++) {
        pq.push([heightMap[0][i], 0, i], [heightMap[m - 1][i], m - 1, i]);
        visited[0][i] = visited[m - 1][i] = true;
    }

    pq.sort(comparator);

    let water = 0;
    let maxHeight = 0;
    const dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]];

    while (pq.length) {
        const [h, r, c] = pq.shift();
        maxHeight = Math.max(maxHeight, h);
        for (const [dx, dy] of dirs) {
            const x = r + dx;
            const y = c + dy;
            if (x < 0 || x >= m || y < 0 || y >= n || visited[x][y]) continue;
            if (heightMap[x][y] < maxHeight) water += maxHeight - heightMap[x][y];
            pq.push([heightMap[x][y], x, y]);
            pq.sort(comparator);
            visited[x][y] = true;
        }
    }

    return water;
}

validWordAbbreviation(string word, string abbr) {
    int i = 0, j = 0;
    while (i < word.size() && j < abbr.size()) {
        if (isdigit(abbr[j])) {
            if (abbr[j] == '0') return false; // leading zero
            int num = 0;
            while (j < abbr.size() && isdigit(abbr[j]))
                num = num * 10 + (abbr[j++] - '0');
            i += num;
        } else {
            if (word[i++] != abbr[j++]) return false;
        }
    }
    return i == word.size() && j == abbr.size();
}

