    const visited = new Set([start]);
    let depth = 0;

    while (q.length) {
        const levelSize = q.length;
        for (let i = 0; i < levelSize; i++) {
            const current = q.shift();
            if (current === end) return depth;

            for (const gene of bank) {
                if (!visited.has(gene)) {
                    let diff = 0;
                    for (let j = 0; j < 8; j++) {
                        if (current[j] !== gene[j]) diff++;
                        if (diff > 1) break;
                    }

                    if (diff === 1) {
                        q.push(gene);
                        visited.add(gene);
                    }
                }
            }
        }
        depth++;
    }
    return -1;
}

