public List<Integer> findAnagrams(String s, String p) {
    List<Integer> result = new ArrayList<>();
    if (s.length() < p.length()) return result;

    int[] s_count = new int[26];
    int[] p_count = new int[26];
    for (char c : p.toCharArray()) p_count[c - 'a']++;

    for (int i = 0; i < s.length(); i++) {
        s_count[s.charAt(i) - 'a']++;
        if (i >= p.length()) s_count[s.charAt(i - p.length()) - 'a']--;
        if (java.util.Arrays.equals(s_count, p_count)) result.add(i - p.length() + 1);
    }

    return result;
}

findAnagrams(s, p) {
    if (s.length < p.length) return [];

    const s_count = new Array(26).fill(0);
    const p_count = new Array(26).fill(0);
    for (const c of p) p_count[c.charCodeAt(0) - 'a'.charCodeAt(0)]++;

    const result = [];
    for (let i = 0; i < s.length; i++) {
        s_count[s.charCodeAt(i) - 'a'.charCodeAt(0)]++;
        if (i >= p.length) s_count[s.charCodeAt(i - p.length) - 'a'.charCodeAt(0)]--;
        if (s_count.join(',') === p_count.join(',')) result.push(i - p.length + 1);
    }

    return result;
}

find_anagrams(s, p):
    if len(s) < len(p):
        return []

    s_count = [0] * 26
    p_count = [0] * 26
    for c in p:
        p_count[ord(c) - ord('a')] += 1

    result = []
    for i in range(len(s)):
        s_count[ord(s[i]) - ord('a')] += 1
        if i >= len(p):
            s_count[ord(s[i - len(p)]) - ord('a')] -= 1
        if s_count == p_count:
            result.append(i - len(p) + 1)

    return result

