public int numberOfArithmeticSlices(int[] nums) {
    int res = 0;
    int n = nums.length;
    Map<Integer, Integer>[] dp = new HashMap[n];

    for (int i = 0; i < n; ++i) {
        dp[i] = new HashMap<>();
        for (int j = 0; j < i; ++j) {
            long diff = (long)nums[i] - (long)nums[j];
            if (diff <= Integer.MIN_VALUE || diff > Integer.MAX_VALUE) continue;

            int delta = (int)diff;
            dp[i].put(delta, dp[i].getOrDefault(delta, 0) + 1);

            if (dp[j].containsKey(delta)) {
                res += dp[j].get(delta);
                dp[i].put(delta, dp[i].get(delta) + dp[j].get(delta));
            }
        }
    }
    return res;
}

numberOfArithmeticSlices(nums) {
    let res = 0;
    const n = nums.length;
    const dp = new Array(n).fill(0).map(() => new Map());

    for (let i = 0; i < n; ++i) {
        for (let j = 0; j < i; ++j) {
            const diff = nums[i] - nums[j];
            if (diff <= Number.MIN_SAFE_INTEGER || diff > Number.MAX_SAFE_INTEGER) continue;

            if (!dp[i].has(diff)) {
                dp[i].set(diff, 0);
            }

            dp[i].set(diff, dp[i].get(diff) + 1);

            if (dp[j].has(diff)) {
                res += dp[j].get(diff);
                dp[i].set(diff, dp[i].get(diff) + dp[j].get(diff));
            }
        }
    }
    return res;
}

