public double[] medianSlidingWindow(int[] nums, int k) {
    TreeMap<Integer, Integer> window = new TreeMap<>();
    int n = nums.length;
    double[] result = new double[n - k + 1];

    for (int i = 0; i < k; i++) {
        window.put(nums[i], window.getOrDefault(nums[i], 0) + 1);
    }

    for (int i = k; i <= n; i++) {
        int cnt = 0, mid1 = 0, mid2 = 0;
        for (Integer num : window.keySet()) {
            cnt += window.get(num);
            if (cnt >= (k + 1) / 2 && mid1 == 0) {
                mid1 = num;
            }
            if (cnt >= (k + 2) / 2) {
                mid2 = num;
                break;
            }
        }

        result[i - k] = ((double) mid1 + mid2) / 2;

        if (i < n) {
            window.put(nums[i], window.getOrDefault(nums[i], 0) + 1);
            window.put(nums[i - k], window.get(nums[i - k]) - 1);
            if (window.get(nums[i - k]) == 0) {
                window.remove(nums[i - k]);
            }
        }
    }

    return result;
}

medianSlidingWindow(nums, k) {
    const window = new SortedSet();
    const medians = [];

    for (let i = 0; i < k; i++) {
        window.add(nums[i]);
    }

    for (let i = k; i <= nums.length; i++) {
        const mid1 = window.at(Math.floor((k - 1) / 2));
        const mid2 = window.at(Math.floor(k / 2));

        medians.push((mid1 + mid2) / 2);

        if (i < nums.length) {
            window.delete(nums[i - k]);
            window.add(nums[i]);
        }
    }

    return medians;
}

