    let sum = nums.reduce((a, b) => a + b);
    if (sum < target || (sum + target) % 2 !== 0) return 0;
    let target_sum = (sum + target) >> 1;
    let dp = new Array(target_sum + 1).fill(0);
    dp[0] = 1;
    for (const num of nums) {
        for (let j = target_sum; j >= num; j--) {
            dp[j] += dp[j - num];
        }
    }
    return dp[target_sum];
}

