    const profit_pool = new MaxPriorityQueue();
    let index = 0;

    for (let i = 0; i < k; i++) {
        while (index < project_pool.length && project_pool[index][0] <= w) {
            profit_pool.insert(project_pool[index++][1]);
        }

        if (!profit_pool.isEmpty()) {
            w += profit_pool.removeMax();
        } else {
