        for (let j = 0; j < n; ++j) {
            dp[i][j] = Infinity;
            for (let k = 0; k < n; ++k) {
                if (ring[k] === key[i]) {
                    const diff = Math.abs(j - k);
                    const step = Math.min(diff, n - diff);
                    dp[i][j] = Math.min(dp[i][j], step + dp[i + 1][k]);
                }
            }
        }
    }

    return dp[0][0] + m;
}

