public int findPairs(int[] nums, int k) {
    if (k < 0) return 0;
    HashSet<Integer> starters = new HashSet<>();
    HashMap<Integer, Integer> occurrences = new HashMap<>();
    for (int num : nums) {
        if (occurrences.containsKey(num + k)) starters.add(num);
