    const pq = new PriorityQueue((a, b) => b - a);
    let time = 0;

    for (const course of courses) {
        time += course[0];
        pq.push(course[0]);

        if (time > course[1]) {
            time -= pq.pop();
        }
    }

    return pq.size();
}

class PriorityQueue {
    constructor(comparator) {
        this.data = [];
        this.comparator = comparator;
    }

    push(item) {
        this.data.push(item);
        this.data.sort(this.comparator);
    }

    pop() {
        return this.data.shift();
    }

    size() {
        return this.data.length;
    }
}

