class Solution {
    public int[] cheapestJump(int[] coins, int maxJump) {
        int n = coins.length;
        int[] dp = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        Arrays.fill(parent, -1);
        dp[0] = coins[0];
        for (int i = 0; i < n; ++i) {
            if (coins[i] == -1) continue;
            for (int j = 1; j <= maxJump && i + j < n; ++j) {
                int next = i + j;
                int cost = coins[next] + dp[i];
                if (cost < dp[next]) {
                    dp[next] = cost;
                    parent[next] = i;
                }
            }
        }
        List<Integer> ansList = new ArrayList<>();
        if (dp[n - 1] == Integer.MAX_VALUE) return new int[0];
        int cur = n - 1;
        while (cur != -1) {
            ansList.add(cur + 1);
            cur = parent[cur];
        }
        Collections.reverse(ansList);
        int[] ans = new int[ansList.size()];
        for (int i = 0; i < ansLIST.size(); i++) {
            ans[i] = ansList.get(i);
        }
        return ans;
    }
}

cheapestJump(coins, maxJump) {
    const n = coins.length;
    const dp = new Array(n).fill(Infinity);
    const parent = new Array(n).fill(-1);
    dp[0] = coins[0];
    for (let i = 0; i < n; ++i) {
        if (coins[i] === -1) continue;
        for (let j = 1; j <= maxJump && i + j < n; ++j) {
            const next = i + j;
            const cost = coins[next] + dp[i];
            if (cost < dp[next]) {
                dp[next] = cost;
                parent[next] = i;
            }
        }
    }
    const ans = [];
    if (dp[n - 1] === Infinity) return ans;
    let cur = n - 1;
    while (cur !== -1) {
        ans.push(cur + 1);
        cur = parent[cur];
    }
    ans.reverse();
    return ans;
}

