    int n = nums.length, maxLength = 0, ans = 0;
    int[] length = new int[n];
    int[] count = new int[n];

    for (int i = 0; i < n; ++i) {
        length[i] = count[i] = 1;
        for (int j = 0; j < i; ++j) {
            if (nums[i] > nums[j]) {
                if (length[i] == length[j] + 1) {
                    count[i] += count[j];
                } else if (length[i] < length[j] + 1) {
                    length[i] = length[j] + 1;
                    count[i] = count[j];
                }
            }
        }
        if (maxLength == length[i]) {
            ans += count[i];
        } else if (maxLength < length[i]) {
            maxLength = length[i];
            ans = count[i];
        }
    }

    return ans;
}

