class Solution {
    public int calPoints(String[] ops) {
        LinkedList<Integer> record = new LinkedList<>();
        for (String op : ops) {
            if (op.equals("+")) {
                record.add(record.getLast() + record.get(record.size() - 2));
            } else if (op.equals("D")) {
                record.add(record.getLast() * 2);
            } else if (op.equals("C")) {
                record.removeLast();
            } else {
                record.add(Integer.parseInt(op));
            }
        }
        return record.stream().mapToInt(Integer::intValue).sum();
    }
}

calPoints(ops) {
    let record = [];
    for (let op of ops) {
        if (op === '+') {
            record.push(record[record.length - 1] + record[record.length - 2]);
        } else if (op === 'D') {
            record.push(record[record.length - 1] * 2);
        } else if (op === 'C') {
            record.pop();
        } else {
            record.push(parseInt(op));
        }
    }
    return record.reduce((a, b) => a + b, 0);
}

