  if (currSum === target) return dfs(nums, visited, 0, target, 0, k - 1);
  for (let i = start; i < nums.length; i++) {
    if (!visited[i] && currSum + nums[i] <= target) {
      visited[i] = true;
      if (dfs(nums, visited, i + 1, target, currSum + nums[i], k)) return true;
      visited[i] = false;
    }
  }
  return false;
}

