        for (let i = 0; i < blacklist.length; ++i) {
            let black = blacklist[i];
            while (idx < black) {
                this.mapping.set(idx++, n - 1);
                n--;
            }
            idx++;
            n--;
        }
        this.last = n;
    }

    pick() {
        const num = Math.floor(Math.random() * this.last);
        return this.mapping.has(num) ? this.mapping.get(num) : num;
    }
}

