int countPalindromicSubsequences(String S) {
    int n = S.length();
    int mod = 1000000007;
    int[][] dp = new int[4][n + 1];

    for (int i = n - 1; i >= 0; i--) {
        for (int j = i + 1; j <= n; j++) {
            int c = S.charAt(i) - 'a';
            dp[c][j] = dp[0][j - 1] + dp[1][j - 1] + dp[2][j - 1] + dp[3][j - 1] - dp[c][i] + 2;
            if (dp[c][j] < 0) dp[c][j] += mod;
        }
    }

    return (dp[0][n] + dp[1][n] + dp[2][n] + dp[3][n]) % mod;
}

countPalindromicSubsequences(s) {
    const n = s.length;
    const MOD = 1000000007;
    const dp = Array.from({ length: 4 }, () => Array(n + 1).fill(0));

    for (let i = n - 1; i >= 0; i--) {
        for (let j = i + 1; j <= n; j++) {
            const c = s.charCodeAt(i) - 97;
            dp[c][j] = dp[0][j - 1] + dp[1][j - 1] + dp[2][j - 1] + dp[3][j - 1] - dp[c][i] + 2;
            dp[c][j] = (dp[c][j] + MOD) % MOD;
        }
    }

    return (dp[0][n] + dp[1][n] + dp[2][n] + dp[3][n]) % MOD;
}

