public int dp(int r1, int c1, int c2, int[][] grid, int[][][] memo) {
    int r2 = r1 + c1 - c2;
    if (r1 == grid.length || r2 == grid.length || c1 == grid.length || c2 == grid.length ||
            grid[r1][c1] == -1 || grid[r2][c2] == -1) {
