    int[][][] dp = new int[n][n][4];
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            if (grid[i][j] > 0) {
                dp[i][j][0] = i > 0 ? dp[i - 1][j][0] + 1 : 1;
                dp[i][j][1] = j > 0 ? dp[i][j - 1][1] + 1 : 1;
            }

    int ans = 0;
    for (int i=n-1; i>=0; --i)
        for (int j=n-1; j>=0; --j)
            if (grid[i][j] > 0) {
                dp[i][j][2] = i < n - 1 ? dp[i + 1][j][2] + 1 : 1;
                dp[i][j][3] = j < n - 1 ? dp[i][j + 1][3] + 1 : 1;
                int cur = Collections.min(Arrays.asList(dp[i][j]));
                ans = Math.max(ans, cur);
            }

    return ans;
}

