public int numRabbits(int[] answers) {
    HashMap<Integer, Integer> count = new HashMap<>();
    int rabbits = 0;
    for(int ans : answers) {
        count.put(ans, count.getOrDefault(ans, 0) + 1);
    }
    for(int key : count.keySet()) {
        int cnt = count.get(key);
        rabbits += (key + cnt) / (key + 1) * (key + 1);
    }
    return rabbits;
}

