public int numBusesToDestination(int[][] routes, int source, int target) {
    if (source == target) return 0;

    Map<Integer, Set<Integer>> stopRouteMap = new HashMap<>();
    for (int i = 0; i < routes.length; i++) {
        for (int stop : routes[i]) {
            stopRouteMap.computeIfAbsent(stop, x -> new HashSet<>()).add(i);
        }
    }

    Queue<Integer> queue = new LinkedList<>();
    Set<Integer> visitedSources = new HashSet<>();

    queue.offer(source);
    visitedSources.add(source);
    int transfers = 0;

    while (!queue.isEmpty()) {
        int size = queue.size();
        while (size-- > 0) {
            int curr = queue.poll(); // Pop from the queue.
            if (curr == target) return transfers;

            for (int route : stopRouteMap.get(curr)) {
                for (int stop : routes[route]) {
                    if (!visitedSources.contains(stop)) {
                        queue.offer(stop);
                        visitedSources.add(stop);
                    }
                }
                // Remove the route from the stop.
                stopRouteMap.get(curr).remove(route);
            }
        }
        transfers++;
    }
    return -1;
}

numBusesToDestination(routes, source, target) {
    if (source === target) return 0;

    const stopRouteMap = new Map();
    for (let i = 0; i < routes.length; i++) {
        for (const stop of routes[i]) {
            if (!stopRouteMap.has(stop)) {
                stopRouteMap.set(stop, new Set());
            }
            stopRouteMap.get(stop).add(i);
        }
    }

    const queue = [source];
    const visitedSources = new Set([source]);
    let transfers = 0;

    while (queue.length) {
        const size = queue.length;
        for (let i = 0; i < size; i++) {
            const curr = queue.shift();
            if (curr === target) return transfers;

            for (const route of stopRouteMap.get(curr)) {
                for (const stop of routes[route]) {
                    if (!visitedSources.has(stop)) {
                        queue.push(stop);
                        visitedSources.add(stop);
                    }
                }
                stopRouteMap.get(curr).delete(route);
            }
        }
        transfers++;
    }
    return -1;
}

