maxPartitionSum(int start, int k, const vector<int>& nums, vector<vector<double>>& memo) {
    if (k == 1) {
        return (accumulate(nums.begin()+start, nums.end(), 0.0)) / (nums.size() - start);
    }
    if (memo[start][k] != -1.0) {
        return memo[start][k];
    }
    double sum = 0, ans = 0;
    for (int i = start; i < nums.size() - k + 1; ++i) {
        sum += nums[i];
        ans = max(ans, sum / (i - start + 1) + maxPartitionSum(i + 1, k - 1, nums, memo));
    }
    memo[start][k] = ans;
    return ans;
}

