                if (visitedBuses.has(bus)) continue;
                visitedBuses.add(bus);
                for (const nextStop of routes[bus]) {
                    if (nextStop === target) return numBuses + 1;
                    q.push(nextStop);
                }
            }
        }
        numBuses++;
    }

    return -1;
}

