    if (n > 1 && s.charAt(0) == '0') {
        res.add("0." + s.substring(1));
        return res;
    }
    res.add(s);
    if (n == 1 || s.charAt(n - 1) == '0') return res;

    for (int i = 1; i < n; i++) {
        res.add(s.substring(0, i) + "." + s.substring(i));
    }
    return res;
}

