java.util.Arrays;
import java.util.Comparator;

public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
    Integer[] jobIdx = new Integer[difficulty.length];
    for (int i = 0; i < difficulty.length; i++) {
        jobIdx[i] = i;
    }
    Arrays.sort(jobIdx, Comparator.comparingInt(i -> difficulty[i]));
    Arrays.sort(worker);

    int i = 0, maxProfit = 0, totalProfit = 0;
    for (int ability : worker) {
        while (i < difficulty.length && ability >= difficulty[jobIdx[i]]) {
            maxProfit = Math.max(maxProfit, profit[jobIdx[i]]);
            i++;
        }
        totalProfit += maxProfit;
    }
    return totalProfit;
}

maxProfitAssignment(difficulty, profit, worker) {
    const jobs = difficulty.map((d, i) => [d, profit[i]]).sort((a, b) => a[0] - b[0]);
    worker.sort((a, b) => a - b);

    let i = 0, maxProfit = 0, totalProfit = 0;
    for (const ability of worker) {
        while (i < difficulty.length && ability >= jobs[i][0]) {
            maxProfit = Math.max(maxProfit, jobs[i][1]);
            i++;
        }
        totalProfit += maxProfit;
    }
    return totalProfit;
}

kSimilarity(const std::string& s1, const std::string& s2) {
    int k = 0;
    std::string temp = s1;

    for (int i = 0; i < temp.length(); ++i) {
        if (temp[i] != s2[i]) {
            int j = i + 1;
            while (temp[j] != s2[i] || s2[j] == temp[j]) {
                ++j;
            }
            std::swap(temp[i], temp[j]);
            k++;
        }
    }
    return k;
}

