public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
    List<int[]> indexMapping = new ArrayList<>();

    for (int i = 0; i < indices.length; i++) {
        if (s.startsWith(sources[i], indices[i])) {
            indexMapping.add(new int[]{indices[i], i});
        }
    }

    indexMapping.sort((a, b) -> a[0] - b[0]);
    StringBuilder result = new StringBuilder();
    int lastIdx = 0;

    for (int[] p : indexMapping) {
        result.append(s, lastIdx, p[0]);
        result.append(targets[p[1]]);
        lastIdx = p[0] + sources[p[1]].length();
    }

    result.append(s.substring(lastIdx));
    return result.toString();
}

findReplaceString(s, indices, sources, targets) {
    const indexMapping = indices
        .map((idx, i) => [s.startsWith(sources[i], idx) ? idx : -1, i])
        .sort((a, b) => a[0] - b[0]);
    let result = "";
    let lastIdx = 0;

    for (const [idx, i] of indexMapping) {
        if (idx >= 0) {
            result += s.slice(lastIdx, idx) + targets[i];
            lastIdx = idx + sources[i].length;
        }
    }

    result += s.slice(lastIdx);
    return result;
}

