String pushDominoes(String dominoes) {
    int n = dominoes.length();
    String prev;
    String cur = dominoes;
    do {
        prev = cur;
        StringBuilder sb = new StringBuilder(prev);
        for (int i = 0; i < n; ++i) {
            if (prev.charAt(i) == 'L' && i > 0 && prev.charAt(i - 1) == '.')
                sb.setCharAt(i - 1, 'L');
            else if (prev.charAt(i) == 'R' && i < n - 1 && prev.charAt(i + 1) == '.')
                sb.setCharAt(i + 1, 'R');
        }
        cur = sb.toString();
    } while (!prev.equals(cur));
    return cur;
}

