        steps++;
        const size = q.length;

        for(let k = 0; k < size; k++) {
            const [currNode, currVisits] = q.shift();

            if(currVisits.toString(2).split('').filter(v => v === '1').length === n) return steps;

            for(const nextNode of graph[currNode]) {
                const nextVisits = currVisits | (1 << nextNode);

                if(!visited[nextNode][nextVisits]) {
                    visited[nextNode][nextVisits] = true;
                    q.push([nextNode, nextVisits]);
                }
            }
        }
    }

    return -1;
}

collections import deque, defaultdict

def shortestPathLength(graph):
    n = len(graph)
    q = deque()

    for i in range(n):
        q.append((i, 1 << i))
    steps = -1
    visited = {i: set() for i in range(n)}

    while q:
        steps += 1
        for _ in range(len(q)):
            currNode, currVisits = q.popleft()

            if bin(currVisits).count('1') == n:
                return steps

            for nextNode in graph[currNode]:
                nextVisits = currVisits | (1 << nextNode)

                if nextVisits not in visited[nextNode]:
                    visited[nextNode].add(nextVisits)
                    q.append((nextNode, nextVisits))

    return -1

class Solution {
