int rectangleArea(vector<vector<int>>& rectangles) {
    int mod = 1e9 + 7;
    vector<int> X;
    map<int,int> Xcompress;
    for(auto r : rectangles){
        X.push_back(r[0]);
        X.push_back(r[2]);
    }
    sort(X.begin(), X.end());
    int idx = 0;
    for(auto x : X){
        if(!Xcompress.count(x))
            Xcompress[x] = idx++;
    }

    vector<vector<int>> events;
    for(auto r : rectangles){
        events.push_back({Xcompress[r[0]], 1, r[1], r[3]});
        events.push_back({Xcompress[r[2]], -1, r[1], r[3]});
    }
    sort(events.begin(), events.end());

    int area = 0;
    vector<int> cnt(idx,0);
    int active = 0;
    for(auto e : events){
        int idx = e[0], type = e[1],	y1 = e[2], y2 = e[3];
        area = (area + (long long)(X[idx+1] - X[idx]) * active % mod) % mod;
        cnt[y1] += type;
        cnt[y2] -= type;
        active = 0;
        for(int i = 0; i < idx; ++i){
            if(cnt[i])
                active += X[i+1] - X[i];
        }
    }
    return area;
}

