kSimilarity(const std::string& s1, const std::string& s2) {
    int k = 0;
    std::string a = s1, b = s2;
    for (int i = 0; i < a.size(); ++i) {
        if (a[i] != b[i]) {
            for (int j = i + 1; j < b.size(); ++j) {
                if (a[i] == b[j] && a[j] != b[j]) {
                    std::swap(a[i], a[j]);
                    k++;
                    break;
                }
            }
        }
    }
    return k;
}

