            for (int j = i + 1; j < b.length(); ++j) {
                if (a.charAt(i) == b.charAt(j) && a.charAt(j) != b.charAt(j)) {
                    a.setCharAt(i, a.charAt(j));
                    a.setCharAt(j, b.charAt(j));
