        int distance = students.first(), seatIndex = 0;

        Integer prev = students.first();
        for (Integer current : students) {
            if (current != prev) {
                int d = (current - prev) / 2;

                if (d > distance) {
                    distance = d;
                    seatIndex = prev + d;
                }
                prev = current;
            }
        }

        if (n - 1 - students.last() > distance)
            seatIndex = n - 1;

        students.add(seatIndex);
        return seatIndex;
    }

