import java.util.Deque;

public int shortestSubarray(int[] nums, int k) {
    int n = nums.length;
    int[] prefixSum = new int[n + 1];
    for (int i = 0; i < n; i++) prefixSum[i + 1] = prefixSum[i] + nums[i];

    int res = n + 1;
    Deque<Integer> dq = new ArrayDeque<>();
    for (int i = 0; i < n + 1; i++) {
        while (!dq.isEmpty() && prefixSum[i] - prefixSum[dq.peek()] >= k) {
            res = Math.min(res, i - dq.poll());
        }
        while (!dq.isEmpty() && prefixSum[i] <= prefixSum[dq.peekLast()]) {
            dq.pollLast();
        }
        dq.offer(i);
    }
    return res <= n ? res : -1;
}

shortestSubarray(nums, k) {
    const n = nums.length;
    const prefixSum = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefixSum[i + 1] = prefixSum[i] + nums[i];

    let res = n + 1;
    const dq = [];
    for (let i = 0; i < n + 1; i++) {
        while (dq.length > 0 && prefixSum[i] - prefixSum[dq[0]] >= k) {
            res = Math.min(res, i - dq.shift());
        }
        while (dq.length > 0 && prefixSum[i] <= prefixSum[dq[dq.length - 1]]) {
            dq.pop();
        }
        dq.push(i);
    }
    return res <= n ? res : -1;
}

