public boolean reorderedPowerOf2(int n) {
    char[] s = String.valueOf(n).toCharArray();
    Arrays.sort(s);
    do {
        if (s[0] != '0' && Integer.bitCount(Integer.parseInt(new String(s))) == 1) {
            return true;
        }
    } while (nextPermutation(s));
    return false;
}

private boolean nextPermutation(char[] s) {
    int i = s.length - 2;
    while (i >= 0 && s[i] >= s[i + 1]) {
        i--;
    }
    if (i == -1) {
        return false;
    }
    int j = s.length - 1;
    while (s[j] <= s[i]) {
        j--;
    }
    char temp = s[i];
    s[i] = s[j];
    s[j] = temp;

    int left = i + 1;
    int right = s.length - 1;
    while (left < right) {
        temp = s[left];
        s[left++] = s[right];
        s[right--] = temp;
    }
    return true;
}

