class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        Arrays.sort(initial);

        Set<Integer> malware = new HashSet<>();
        for (int i : initial) {
            malware.add(i);
        }

        int minNode = initial[0], minSpread = n + 1;
        for (int node : initial) {
            Queue<Integer> q = new LinkedList<>();
            boolean[] visited = new boolean[n];

            for (int otherNode : initial) {
                if (node != otherNode) {
                    q.offer(otherNode);
                    visited[otherNode] = true;
                }
            }

            while (!q.isEmpty()) {
                int cur = q.poll();
                for (int next = 0; next < n; ++next) {
                    if (graph[cur][next] == 1 && !visited[next] && !malware.contains(next)) {
                        visited[next] = true;
                        q.offer(next);
                    }
                }
            }

            int spread = 0;
            for (boolean v : visited) {
                spread += v ? 1 : 0;
            }

            if (spread < minSpread) {
                minNode = node;
                minSpread = spread;
            }
        }

        return minNode;
    }
}

minMalwareSpread(graph, initial) {
    const n = graph.length;
    initial.sort((a, b) => a - b);

    const malware = new Set(initial);

    let minNode = initial[0];
    let minSpread = n + 1;

    for (const node of initial) {
        const q = [];
        const visited = new Array(n).fill(false);

        for (const otherNode of initial) {
            if (node !== otherNode) {
                q.push(otherNode);
                visited[otherNode] = true;
            }
        }

        while (q.length) {
            const cur = q.shift();
            for (let next = 0; next < n; ++next) {
                if (graph[cur][next] === 1 && !visited[next] && !malware.has(next)) {
                    visited[next] = true;
                    q.push(next);
                }
            }
        }

        const spread = visited.reduce((acc, v) => acc + (v ? 1 : 0), 0);

        if (spread < minSpread) {
            minNode = node;
            minSpread = spread;
        }
    }

    return minNode;
}

