int distinctSubseqII(String s) {
    int mod = (int) (1e9 + 7);
    int n = s.length();
    int[] dp = new int[n + 1];
    dp[0] = 1;
    int[] last = new int[26];
    Arrays.fill(last, -1);

    for (int i = 1; i <= n; ++i) {
        dp[i] = (dp[i - 1] * 2) % mod;
        if (last[s.charAt(i - 1) - 'a'] != -1) {
            dp[i] = (dp[i] - dp[last[s.charAt(i - 1) - 'a']] + mod) % mod;
        }
        last[s.charAt(i - 1) - 'a'] = i - 1;
    }

    dp[n] = (dp[n] - 1 + mod) % mod;
    return dp[n];
}

