public boolean validateStackSequences(int[] pushed, int[] popped) {
    Stack<Integer> stack = new Stack<>();
    int popIndex = 0;

    for (int pushValue : pushed) {
        stack.push(pushValue);
        while (!stack.isEmpty() && stack.peek() == popped[popIndex]) {
            stack.pop();
            popIndex++;
        }
    }

    return stack.isEmpty();
}

