public String largestTimeFromDigits(int[] A) {
    Arrays.sort(A);
    for (int i = 3; i >= 0; i--) {
        if (A[i] <= 2) {
            for (int j = 3; j >= 0; j--) {
                if ((A[i] != 2 || A[j] <= 3) && A[j] != A[i]) {
                    for (int k = 3; k >= 0; k--) {
                        if (A[k] <= 5 && A[k] != A[i] && A[k] != A[j]) {
                            int l = 6 - i - j - k;
                            return String.format("%d%d:%d%d", A[i], A[j], A[k], A[l]);
                        }
                    }
                }
            }
        }
    }
    return "";
}

largestTimeFromDigits(arr) {
    let maxTime = -1;
    for (let i = 0; i < 4; i++) {
        if (arr[i] > 2) continue;
        for (let j = 0; j < 4; j++) {
            if (j === i || (arr[i] === 2 && arr[j] > 3)) continue;
            for (let k = 0; k < 4; k++) {
                if (k === i || k === j || arr[k] > 5) continue;
                let l = 6 - i - j - k;
                let time = 60 * (10 * arr[i] + arr[j]) + 10 * arr[k] + arr[l];
                maxTime = Math.max(maxTime, time);
            }
        }
    }
    if (maxTime === -1) return "";
    else return `${String(Math.trunc(maxTime / 60)).padStart(2, '0')}:${String(maxTime % 60).padStart(2, '0')}`;
}

