class TimeMap {
    private Map<String, TreeMap<Integer, String>> data;

    public TimeMap() {
        data = new HashMap();
    }

    public void set(String key, String value, int timestamp) {
        data.putIfAbsent(key, new TreeMap<>());
        data.get(key).put(timestamp, value);
    }

    public String get(String key, int timestamp) {
        if (!data.containsKey(key)) return "";
        Integer prevTimeStamp = data.get(key).floorKey(timestamp);
        return prevTimeStamp == null ? "" : data.get(key).get(prevTimeStamp);
    }
}

TimeMap {
    constructor() {
        this.data = new Map();
    }

    set(key, value, timestamp) {
        if (!this.data.has(key)) {
            this.data.set(key, []);
        }
        this.data.get(key).push({ timestamp, value });
    }

    get(key, timestamp) {
        if (!this.data.has(key)) return "";
        const values = this.data.get(key);
        let left = 0, right = values.length - 1;
        while (left < right) {
            let mid = Math.floor((left + right + 1) / 2);
            if (values[mid].timestamp > timestamp) {
                right = mid - 1;
            } else {
                left = mid;
            }
        }
        return values[left].timestamp <= timestamp ? values[left].value : "";
    }
}

