        if (nums[index] % 2 == 0) {
            even_sum -= nums[index];
        }
        nums[index] += value;
        if (nums[index] % 2 == 0) {
            even_sum += nums[index];
        }
        answer[i] = even_sum;
    }

    return answer;
}

