    let res = Infinity;

    let targets = [tops[0], bottoms[0]];

    for (let target of targets) {
        let top_rot = 0;
        let bot_rot = 0;

        for (let i = 0; i < tops.length; ++i) {
            if (tops[i] !== target && bottoms[i] !== target) {
                top_rot = bot_rot = Infinity;
                break;
            }

            if (tops[i] !== target) {
                top_rot++;
            }

            if (bottoms[i] !== target) {
                bot_rot++;
            }
        }
        res = Math.min(res, top_rot, bot_rot);
    }

    return res === Infinity ? -1 : res;
}

