public int numDupDigitsAtMostN(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        HashSet<Integer> digits = new HashSet<>();
        int num = i;
        while (num != 0) {
            int digit = num % 10;
            if (digits.contains(digit)) {
                count++;
                break;
            } else {
                digits.add(digit);
            }
            num /= 10;
        }
    }
    return count;
}

