    if (!graph.containsKey(node)) return node == destination;
    if (visited[node] != 0) return visited[node] == 2;

    visited[node] = 1;
    for (int neighbor : graph.get(node)) {
        if (!dfs(neighbor, graph, visited, destination)) return false;
    }

    visited[node] = 2;
    return true;
}

