    while (current) {
        while (stack.length > 0 && result[stack[stack.length - 1]] < current.val) {
            result[stack.pop()] = current.val;
        }
        result.push(current.val);
        stack.push(result.length - 1);
        current = current.next;
    }

    while (stack.length > 0) {
        result[stack.pop()] = 0;
    }

    return result;
}

