    const labelCount = {};
    let ans = 0;

    for (const [value, label] of items) {
        if (!labelCount.hasOwnProperty(label)) {
            labelCount[label] = 0;
        }
        if (labelCount[label] < useLimit) {
            ans += value;
            labelCount[label]++;
            numWanted--;
            if (numWanted === 0) break;
        }
    }

    return ans;
}

