public int[] gardenNoAdj(int n, int[][] paths) {
    List<Set<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new HashSet<>());
    }
    for (int[] path : paths) {
        graph.get(path[0] - 1).add(path[1] - 1);
        graph.get(path[1] - 1).add(path[0] - 1);
    }
    int[] result = new int[n];
    for (int i = 0; i < n; i++) {
        Set<Integer> usedFlowers = new HashSet<>();
        for (int neighbor : graph.get(i)) {
            usedFlowers.add(result[neighbor]);
        }
        for (int flower = 1; flower <= 4; flower++) {
            if (!usedFlowers.contains(flower)) {
                result[i] = flower;
                break;
            }
        }
    }
    return result;
}

gardenNoAdj(n, paths) {
    const graph = Array.from({ length: n }, () => new Set());

    for (const [x, y] of paths) {
        graph[x - 1].add(y - 1);
        graph[y - 1].add(x - 1);
    }

    const result = Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        const usedFlowers = new Set(graph[i].map(neighbor => result[neighbor]));

        for (let flower = 1; flower <= 4; flower++) {
            if (!usedFlowers.has(flower)) {
                result[i] = flower;
                break;
            }
        }
    }
    return result;
}

