int maxSumAfterPartitioning(int[] arr, int k) {
    int n = arr.length;
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; ++i) {
        int current_max = 0;
        for (int j = 1; j <= k && i - j >= 0; ++j) {
            current_max = Math.max(current_max, arr[i - j]);
            dp[i] = Math.max(dp[i], dp[i - j] + current_max * j);
        }
    }
    return dp[n];
}

