minimumSemesters(int n, vector<vector<int>>& relations) {
    vector<int> in_degree(n + 1, 0);
    vector<vector<int>> graph(n + 1);

    for (auto& relation : relations) {
        graph[relation[0]].push_back(relation[1]);
        in_degree[relation[1]]++;
    }

    queue<int> q;
    for (int i = 1; i <= n; i++) {
        if (in_degree[i] == 0) {
            q.push(i);
        }
    }

    int semesters = 0;
    while (!q.empty()) {
        int size = q.size();
        semesters++;
        while (size--) {
            int course = q.front();
            q.pop();
            n--;

            for (int next : graph[course]) {
                if (--in_degree[next] == 0) {
                    q.push(next);
                }
            }
        }
    }

    return n == 0 ? semesters : -1;
}

