numRollsToTarget(int n, int k, int target) {
    const int MOD = 1e9 + 7;
    vector<vector<int>> dp(n + 1, vector<int>(target + 1, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = i; j <= target; ++j) {
            for (int d = 1; d <= k && j - d >= 0; ++d) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - d]) % MOD;
            }
        }
    }
    return dp[n][target];
}

