public List<Integer> countSteppingNumbers(int low, int high) {
    List<Integer> results = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        int prev = -1;
        int j = i;
        boolean isStepping = true;
        while (j > 0) {
            int digit = j % 10;
            if (prev != -1 && Math.abs(prev - digit) != 1) {
                isStepping = false;
                break;
            }
            prev = digit;
            j /= 10;
        }
        if (isStepping) results.add(i);
    }
    return results;
}

