class ZeroEvenOdd {
    private int n;
    private int cnt;
    private Lock lock;
    private Condition condition;

    public ZeroEvenOdd(int n) {
        this.n = n;
        cnt = 1;
        lock = new ReentrantLock();
        condition = lock.newCondition();
    }

    public void zero(IntConsumer printNumber) throws InterruptedException {
        for(int i = 1; i <= n; i++) {
            lock.lock();
            try {
                while (cnt % 2 == 0)
                    condition.await();
                printNumber.accept(0);
                cnt++;
                condition.signalAll();
            } finally {
                lock.unlock();
            }
        }
    }

    public void even(IntConsumer printNumber) throws InterruptedException {
        for(int i = 2; i <= n; i+=2) {
            lock.lock();
            try {
                while (cnt != 2 * i)
                    condition.await();
                printNumber.accept(i);
                cnt++;
                condition.signalAll();
            } finally {
                lock.unlock();
            }
        }
    }

    public void odd(IntConsumer printNumber) throws InterruptedException {
        for(int i = 1; i <= n; i+=2) {
            lock.lock();
            try {
                while (cnt != 2 * i - 1)
                    condition.await();
                printNumber.accept(i);
                cnt++;
                condition.signalAll();
            } finally {
                lock.unlock();
            }
        }
    }
}

