    const counts = new Map();

    for (const num of arr1) {
        counts.set(num, (counts.get(num) || 0) + 1);
    }

    const result = [];

    for (const num of arr2) {
        while (counts.get(num) > 0) {
            result.push(num);
            counts.set(num, counts.get(num) - 1);
        }
    }

    Array.from(counts.entries())
        .sort(([a], [b]) => a - b)
        .forEach(([num, count]) => {
            while (count--) {
                result.push(num);
            }
        });

    return result;
}

