class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        Map<String, Integer> index = new HashMap<>();
        int num_skills = req_skills.length;
        for (int i = 0; i < num_skills; i++) {
            index.put(req_skills[i], i);
        }

        List<Integer> sks = new ArrayList<>();
        for (int i = 0; i < people.size(); i++) {
            int cur = 0;
            for (String s : people.get(i)) {
                cur |= 1 << index.get(s);
            }
            sks.add(cur);
        }

        int INF = 64;
        int[] dp = new int[1 << num_skills];
        int[] parent = new int[1 << num_skills];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 0; i < people.size(); i++) {
            int hiskills = sks.get(i);
            for (int done = (1 << num_skills) - 1; done >= 0; done--) {
                int withhim = done | hiskills;
                if (dp[withhim] > dp[done] + 1) {
                    dp[withhim] = dp[done] + 1;
                    parent[withhim] = done;
                }
            }
        }

        int[] ans = new int[dp[(1 << num_skills) - 1]];
        int cur = (1 << num_skills) - 1;
        int t = dp[(1 << num_skills) - 1] - 1;

        for (int i = people.size() - 1; i >= 0; i--) {
            int old = parent[cur];
            int diff = cur ^ old;
            boolean isEssential = (sks.get(i) & diff) > 0;
            if (isEssential) {
                ans[t] = i;
                t--;
            }
            cur = old;
        }
        return ans;
    }
}

smallestSufficientTeam(req_skills, people) {
    const skill_to_int = new Map()
    req_skills.forEach((v, i) => skill_to_int.set(v, i))

    const people_int = people.map(person =>
        person.reduce((skills, p) => skills | 1 << skill_to_int.get(p), 0)
    )

    const n = req_skills.length
    const INF = 64
    const dp = Array(1 << n).fill(INF)
    const parent = Array(1 << n).fill(0)

    dp[0] = 0

    for (let i = 0; i < people.length; i++) {
        for (let skills_done = (1 << n) - 1; skills_done >= 0; skills_done--) {
            const with_person_skills = skills_done | people_int[i]
            if (dp[with_person_skills] > dp[skills_done] + 1) {
                dp[with_person_skills] = dp[skills_done] + 1
                parent[with_person_skills] = skills_done
            }
        }
    }

    const result = Array(dp[(1 << n) - 1])
    let cur = (1 << n) - 1
    let t = result.length - 1

    for (let i = people.length - 1; i >= 0; i--) {
        const old = parent[cur]
        const diff = cur ^ old
        const is_essential = (people_int[i] & diff) > 0
        if (is_essential) {
            result[t] = i
            t -= 1
        }
        cur = old
    }

    return result
