public class Solution {
    public int[] getMaxSumAndCount(String[] board) {
        int mod = 1000000007;
        int n = board.length;
        int[][][] dp = new int[n][n][2];
        dp[n - 1][n - 1][1] = 1;

        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (board[i].charAt(j) == 'X' || (i == n - 1 && j == n - 1)) continue;
                int currVal = board[i].charAt(j) == 'E' ? 0 : board[i].charAt(j) - '0';
                int[] up = i > 0 ? dp[i - 1][j] : new int[]{-1, 0};
                int[] left = j > 0 ? dp[i][j - 1] : new int[]{-1, 0};
                int[] diag = i > 0 && j > 0 ? dp[i - 1][j - 1] : new int[]{-1, 0};

                int[] maxArray = getMax(up, left, diag);
                if (maxArray[0] == -1) continue;

                dp[i][j][0] = maxArray[0] + currVal;
                if (Arrays.equals(up, maxArray)) dp[i][j][1] = (dp[i][j][1] + up[1] % mod) % mod;
                if (Arrays.equals(left, maxArray)) dp[i][j][1] = (dp[i][j][1] + left[1] % mod) % mod;
                if (Arrays.equals(diag, maxArray)) dp[i][j][1] = (dp[i][j][1] + diag[1] % mod) % mod;
            }
        }
        return dp[0][0];
    }

    public int[] getMax(int[] a, int[] b, int[] c) {
        if (a[0] >= b[0] && a[0] >= c[0]) return a;
        if (b[0] >= a[0] && b[0] >= c[0]) return b;
        return c;
    }
}

getMaxSumAndCount(board) {
    const mod = 1000000007;
    const n = board.length;
    const dp = Array.from({ length: n }, () => Array.from({ length: n }, () => [0, 0]));
    dp[n - 1][n - 1] = [0, 1];

    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            if (board[i][j] === 'X' || (i === n - 1 && j === n - 1)) continue;
            const currVal = board[i][j] === 'E' ? 0 : parseInt(board[i][j]);
            const up = i > 0 ? dp[i - 1][j] : [-1, 0];
            const left = j > 0 ? dp[i][j - 1] : [-1, 0];
            const diag = i > 0 && j > 0 ? dp[i - 1][j - 1] : [-1, 0];

            const maxArray = getMax(up, left, diag);
            if (maxArray[0] === -1) continue;

            dp[i][j][0] = maxArray[0] + currVal;
            if (arraysEqual(up, maxArray)) dp[i][j][1] = (dp[i][j][1] + up[1] % mod) % mod;
            if (arraysEqual(left, maxArray)) dp[i][j][1] = (dp[i][j][1] + left[1] % mod) % mod;
            if (arraysEqual(diag, maxArray)) dp[i][j][1] = (dp[i][j][1] + diag[1] % mod) % mod;
        }
