numDistinctRepeatedSubstrings(const string& s) {
    unordered_set<string> seen;
    for (int len = s.length() / 2; len >= 1; len--) {
        for (int i = 0; i <= s.length() - 2 * len; i++) {
            string substr = s.substr(i, len);
            if (s.find(substr, i + len) != string::npos)
                seen.insert(substr);
        }
    }
    return seen.size();
}

