class Solution {
    public int[][] diagonalSort(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        for (int i = 0; i < m; ++i) {
            PriorityQueue<Integer> pq = new PriorityQueue<>();
            int row = i, col = 0;
            while (row < m && col < n) {
                pq.offer(mat[row++][col++]);
            }
            row = i; col = 0;
            while (row < m && col < n) {
                mat[row++][col++] = pq.poll();
            }
        }
        for (int i = 1; i < n; ++i) {
            PriorityQueue<Integer> pq = new PriorityQueue<>();
            int row = 0, col = i;
            while (row < m && col < n) {
                pq.offer(mat[row++][col++]);
            }
            row = 0; col = i;
            while (row < m && col < n) {
                mat[row++][col++] = pq.poll();
            }
        }
        return mat;
    }
}

diagonalSort(mat) {
    const m = mat.length, n = mat[0].length;
    for (let i = 0; i < m; ++i) {
        let pq = [];
        let [row, col] = [i, 0];
        while (row < m && col < n) {
            pq.push(mat[row++][col++]);
        }
        pq.sort((a, b) => a - b);
        [row, col] = [i, 0];
        while (row < m && col < n) {
            mat[row++][col++] = pq.shift();
        }
    }
    for (let i = 1; i < n; ++i) {
        let pq = [];
        let [row, col] = [0, i];
        while (row < m && col < n) {
            pq.push(mat[row++][col++]);
        }
        pq.sort((a, b) => a - b);
        [row, col] = [0, i];
        while (row < m && col < n) {
            mat[row++][col++] = pq.shift();
        }
    }
    return mat;
}

int closedIsland(int[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == 0 && dfs(grid, i, j)) {
                count++;
            }
        }
    }
    return count;
}

private boolean dfs(int[][] grid, int i, int j) {
    if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length) {
        return false;
    }

    if (grid[i][j] == 1) {
        return true;
    }

    grid[i][j] = 1;

    boolean up = dfs(grid, i - 1, j);
    boolean down = dfs(grid, i + 1, j);
    boolean left = dfs(grid, i, j - 1);
    boolean right = dfs(grid, i, j + 1);

    return up && down && left && right;
}

