int mod = 1e9 + 7;

int numOfWays(int steps, int arrLen) {
  int max_pos = min(steps / 2, arrLen - 1);
  vector<vector<int>> dp(2, vector<int>(max_pos + 1));
  dp[0][0] = 1;
  for (int s = 1; s <= steps; ++s) {
    for (int p = 0; p <= max_pos; ++p) {
      dp[s % 2][p] = dp[(s - 1) % 2][p];
      if (p > 0) {
        dp[s % 2][p] += dp[(s - 1) % 2][p - 1];
      }
      if (p < max_pos) {
        dp[s % 2][p] += dp[(s - 1) % 2][p + 1];
      }
      dp[s % 2][p] %= mod;
    }
  }
  return dp[steps % 2][0];
}

