    while (n) {
        let rem = Number(n % 16n);
        if (rem === 1) hex = 'I' + hex;
        else if (rem === 0) hex = 'O' + hex;
        else if (rem > 9) hex = String.fromCharCode(rem - 10 + 'A'.charCodeAt(0)) + hex;
        else return 'ERROR';
        n /= 16n;
    }
    return hex;
}

