sum_of_divisors_with_four_divisors(const std::vector<int>& nums) {
    int sum = 0;
    for (int num : nums) {
        int div_count = 0;
        int div_sum = 0;

        for (int i = 1; i * i <= num; ++i) {
            if (num % i == 0) {
                div_sum += i;
                ++div_count;

                if (num / i != i) {
                    div_sum += (num / i);
                    ++div_count;
                }
            }

            if (div_count > 4) {
                break;
            }
        }

        if (div_count == 4) {
            sum += div_sum;
        }
    }

    return sum;
}

