String dayOfTheWeek(int day, int month, int year) {
    String[] days = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    if (month < 3) {
        month += 12;
        year -= 1;
    }
    int k = year % 100;
