public String reverseParentheses(String s) {
    Stack<Character> st = new Stack<>();
    String result = "";

    for (char c : s.toCharArray()) {
        if (c != ')') {
            st.push(c);
        } else {
            String temp = "";
            while (!st.empty() && st.peek() != '(') {
                temp += st.pop();
            }
            if (!st.empty()) st.pop(); // Remove '('
            for (char t : temp.toCharArray()) {
                st.push(t);
            }
        }
    }

    while (!st.empty()) {
        result = st.pop() + result;
    }

    return result;
}

