    if (c) pq.push([-c, 'c']);

    pq.sort((x, y) => x[0] - y[0]);

    while (pq.length) {
        let curr = pq.pop();
        if (res.length >= 2 && res[res.length - 1] === curr[1] && res[res.length - 2] === curr[1]) {
            if (!pq.length) break;
            let next = pq.pop();
            res += next[1];
            if (next[0] < -1) pq.push([next[0] + 1, next[1]]);
            pq.push(curr);
        } else {
            res += curr[1];
            if (curr[0] < -1) pq.push([curr[0] + 1, curr[1]]);
        }
        pq.sort((x, y) => x[0] - y[0]);
    }

    return res;
}

