import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < edges.length; i++) {
            graph.get(edges[i][0]).add(new Edge(edges[i][1], succProb[i]));
            graph.get(edges[i][1]).add(new Edge(edges[i][0], succProb[i]));
        }

        double[] maxProb = new double[n];
        maxProb[start] = 1;

        PriorityQueue<Edge> pq = new PriorityQueue<>((a, b) -> Double.compare(b.prob, a.prob));
        pq.offer(new Edge(start, 1));

        while (!pq.isEmpty()) {
            Edge edge = pq.poll();
            int node = edge.to;
            double prob = edge.prob;

            if (node == end) {
                return prob;
            }

            if (prob < maxProb[node]) {
                continue;
            }

            for (Edge e : graph.get(node)) {
                double newProb = prob * e.prob;
                if (newProb > maxProb[e.to]) {
                    maxProb[e.to] = newProb;
                    pq.offer(new Edge(e.to, newProb));
                }
            }
        }

        return 0;
    }

    private static class Edge {
        int to;
        double prob;

        Edge(int to, double prob) {
            this.to = to;
            this.prob = prob;
        }
    }
}

maxProbability(n, edges, succProb, start, end) {
  const graph = new Array(n).fill(null).map(() => []);
  for (let i = 0; i < edges.length; i++) {
    const [a, b] = edges[i];
    graph[a].push([b, succProb[i]]);
    graph[b].push([a, succProb[i]]);
  }

  const maxProb = new Array(n).fill(0);
  maxProb[start] = 1;

  const pq = [[1, start]];

  while (pq.length) {
    const [prob, node] = pq.pop();

    if (node === end) {
      return prob;
    }

    if (prob < maxProb[node]) {
      continue;
    }

    for (const [neighbor, edgeProb] of graph[node]) {
      const newProb = prob * edgeProb;
      if (newProb > maxProb[neighbor]) {
        maxProb[neighbor] = newProb;
        pq.push([newProb, neighbor]);

        // Re-sort the queue, so it stays a max heap.
        pq.sort(([a], [b]) => b - a);
      }
    }
  }

  return 0;
}

