        freq_map[s[j]]--;
        while (i < n && ['Q', 'W', 'E', 'R'].every(c => (freq_map[c] || 0) <= n / 4)) {
            result = Math.min(result, j - i + 1);
            freq_map[s[i]]++;
            i++;
        }
    }
    return result;
}

