public int maxProfit(int[] startTime, int[] endTime, int[] profit) {
    int n = startTime.length;
    Job[] jobs = new Job[n];

    for (int i = 0; i < n; i++) {
        jobs[i] = new Job(startTime[i], endTime[i], profit[i]);
    }

    Arrays.sort(jobs, (a, b) -> a.end - b.end);

    int[] memo = new int[n];
    Arrays.fill(memo, -1);
    return maxProfitHelper(jobs, memo, n - 1);
