}

tilingRectangle(int n, int m) {
    if (n > m) std::swap(n, m);
    if (n == 1) return m;
    if (n == m) return 1;

    int res = INT_MAX;
    for (int a = 1; a <= n/2; ++a) {
        res = std::min(res, tilingRectangle(a, m) + tilingRectangle(n - a, m));
    }
    for (int b = 1; b <= m/2; ++b) {
        res = std::min(res, tilingRectangle(n, b) + tilingRectangle(n, m - b));
    }
    return res;
}

int tilingRectangle(int n, int m) {
