public String largestMultipleOfThree(int[] digits) {
    Arrays.sort(digits);
    int sum = 0;
    for (int digit : digits) {
        sum += digit;
    }

    if (sum % 3 == 0) {
        if (digits[0] == 0) return "0";
        StringBuilder result = new StringBuilder();
        for (int i = digits.length - 1; i >= 0; --i) {
            result.append(digits[i]);
        }
        return result.toString();
    }

    List<Integer>[] mod = new List[3];
    for (int i = 0; i < 3; ++i) {
        mod[i] = new ArrayList<Integer>();
    }
    for (int digit : digits) {
        mod[digit % 3].add(digit);
    }

    if (sum % 3 == 1) {
        if (!mod[1].isEmpty()) {
            mod[1].remove(mod[1].size() - 1);
        } else {
            mod[2].remove(mod[2].size() - 1);
            mod[2].remove(mod[2].size() - 1);
        }
    } else {
        if (!mod[2].isEmpty()) {
            mod[2].remove(mod[2].size() - 1);
        } else {
            mod[1].remove(mod[1].size() - 1);
            mod[1].remove(mod[1].size() - 1);
        }
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < 3; ++i) {
        for (int digit : mod[i]) {
            result.append(digit);
        }
    }

    result.reverse();
    if (result.length() == 0 || result.charAt(0) == '0') {
        return "0";
    }

    return result.toString();
}

largestMultipleOfThree(digits) {
    digits.sort((a, b) => b - a);
    const sum = digits.reduce((a, b) => a + b, 0);

    if (sum % 3 === 0) {
        if (digits[digits.length - 1] === 0) return "0";
        return digits.join("");
    }

    let mod = new Array(3).fill(null).map(() => []);
    for (let digit of digits) {
        mod[digit % 3].push(digit);
    }

    if (sum % 3 === 1) {
        if (mod[1].length > 0) {
            mod[1].pop();
        } else {
            mod[2].pop(), mod[2].pop();
        }
    } else {
        if (mod[2].length > 0) {
            mod[2].pop();
        } else {
            mod[1].pop(), mod[1].pop();
        }
    }

    let result = mod.flat().join("");
    result = Array.from(result).sort((a, b) => b - a).join("");

    if (!result || result[0] === "0") {
        return "0";
    }

    return result;
}

