    let mid = Math.floor((intLength + 1) / 2);
    let limit = Math.pow(10, mid) - 1;

    for (let i = 0; i <= limit; i++) {
        let num = i.toString();
        let rev = num.split('').reverse().join('');
        if (intLength % 2 !== 0) 
            rev = rev.slice(1);
        let palindrome = parseInt(num + rev);
        if (palindrome > 0)
            k--;
        if (k === 0)
            return palindrome;
    }
    return -1;
}

