            (row === col && Array(3).fill().every((_, i) => grid[i][i] === player)) ||
            (row + col === 2 && Array(3).fill().every((_, i) => grid[i][2 - i] === player))) {
            return player === 1 ? "A" : "B";
        }
        player = 3 - player;
    }
    return moves.length === 9 ? "Draw" : "Pending";
}

