min_changes_to_divide_string(const std::string& s, int k) {
    int n = s.length();
    if (n % k != 0) return -1;
    int chunk_count = n / k;
    int res = 0;
    for (int i = 0; i < k; ++i) {
        int counts[26] = {0};
        for (int j = i; j < n; j += k) {
            ++counts[s[j] - 'a'];
        }
        int max_count = *std::max_element(counts, counts + 26);
        res += chunk_count - max_count;
    }
    return res;
}

