num_steps(const std::string& s) {
    int steps = 0, carry = 0;
    for (int i = s.length() - 1; i > 0; --i) {
        int bit = s[i] - '0';
        if (bit && carry) {
            carry = 1;
            steps += 2;
        } else if (bit || carry) {
            carry ^= 1;
            steps += 2;
        } else {
            steps++;
        }
    }

    return steps + carry;
}

