    for (const [key, value] of [...counts.entries()].sort((a, b) => a[0] - b[0])) {
        if (value > 0) {
            for (let i = k - 1; i >= 0; --i) {
                if ((counts.get(key + i) || 0) < value) return false;
                counts.set(key + i, counts.get(key + i) - value);
            }
        }
    }

    return true;
}

