        for (int[] edge : edges) {
            adjList.get(edge[1]).add(edge[0]);
        }
        for (int i = 0; i < n; ++i) {
            boolean[] visited = new boolean[n];
            findAncestors(i, adjList, visited, ans.get(i));
            Collections.sort(ans.get(i));
        }
