import java.util.Comparator;

public class Solution {
    public String rankTeams(String[] votes) {
        int teams = votes[0].length();
        int[][] ranks = new int[26][teams];

        for (String vote : votes) {
            for (int i = 0; i < teams; ++i) {
                ranks[vote.charAt(i) - 'A'][i]++;
            }
        }

        Character[] result = new Character[teams];
        for (int i = 0; i < teams; ++i) {
            result[i] = votes[0].charAt(i);
        }

        Arrays.sort(result, new Comparator<Character>() {
            public int compare(Character a, Character b) {
                for (int i = 0; i < teams; ++i) {
                    if (ranks[a - 'A'][i] != ranks[b - 'A'][i]) {
                        return ranks[b - 'A'][i] - ranks[a - 'A'][i];
                    }
                }
                return a.compareTo(b);
            }
        });

        StringBuilder sb = new StringBuilder();
        for (Character ch : result) {
            sb.append(ch);
        }
        return sb.toString();
    }
}

rankTeams(votes) {
    const teams = votes[0].length;
    const ranks = Array.from({ length: 26 }, () => Array(teams).fill(0));

    for (const vote of votes) {
        for (let i = 0; i < teams; ++i) {
            ranks[vote.charCodeAt(i) - "A".charCodeAt(0)][i]++;
        }
    }

    const result = [...votes[0]];
    result.sort((a, b) => {
        for (let i = 0; i < teams; ++i) {
            if (ranks[a.charCodeAt(0) - "A".charCodeAt(0)][i] !== ranks[b.charCodeAt(0) - "A".charCodeAt(0)][i]) {
                return ranks[b.charCodeAt(0) - "A".charCodeAt(0)][i] - ranks[a.charCodeAt(0) - "A".charCodeAt(0)][i];
            }
        }
        return a.localeCompare(b);
    });

    return result.join("");
}

rank_teams(votes):
    teams = len(votes[0])
    ranks = [[0] * teams for _ in range(26)]

    for vote in votes:
        for i in range(teams):
            ranks[ord(vote[i]) - ord('A')][i] += 1

    result = list(votes[0])
    result.sort(key=lambda ch: tuple([-ranks[ord(ch) - ord('A')][i] for i in range(teams)] + [ch]))
    return ''.join(result)

