    for (let i = 0; i < n; i++) {
        if (manager[i] !== -1) {
            subordinates[manager[i]].push(i);
        }
    }

    const queue = [[headID, 0]];
    let totalTime = 0;

    while (queue.length) {
        const [current, time] = queue.shift();
        totalTime = Math.max(totalTime, time);
        for (const sub of subordinates[current]) {
            queue.push([sub, time + informTime[current]]);
        }
    }

    return totalTime;
}

