    let probability = 0.0;
    for (const neighbor of graph[node]) {
        if (neighbor !== parent) {
            probability += dfs(neighbor, node, t - 1, target, graph);
        }
    }
    return probability / (graph[node].length - (parent === -1 ? 0 : 1));
}

