private boolean dfs(int[][] grid, int x, int y, int m, int n, boolean[][] visited) {
    if (x < 0 || y < 0 || x >= m || y >= n || visited[x][y]) return false;
    if (x == m - 1 && y == n - 1) return true;

    visited[x][y] = true;

    int[] next_x = {-1, 0, 1, 0};
    int[] next_y = {0, 1, 0, -1};

    for (int i = 0; i < 4; i++) {
        int dx = x + next_x[i];
        int dy = y + next_y[i];

        if (dfs(grid, dx, dy, m, n, visited)) return true;
    }

    return false;
}

