        else:
            i += 1

    dp[0][0] = 1
    for i in range(n):
        for j in range(m):
            for k in range(2):
                for c in range(ord('a'), ord(s2[i] if k else 'z') + 1):
                    e = j
                    while e and (chr(c) != evil[e]):
                        e = lps[e - 1]

