private void dfs(List<String> happyStrings, int n, String s, char prev) {
    if (s.length() == n) {
        happyStrings.add(s);
        return;
    }
    for (char c = 'a'; c <= 'c'; c++) {
        if (c != prev) {
            dfs(happyStrings, n, s + c, c);
        }
    }
