public String entityParser(String text) {
    HashMap<String, Character> entities = new HashMap<String, Character>();
    entities.put("&quot;", '\"');
    entities.put("&apos;", '\'');
    entities.put("&amp;", '&');
    entities.put("&gt;", '>');
    entities.put("&lt;", '<');
    entities.put("&frasl;", '/');

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < text.length(); ++i) {
        if (text.charAt(i) == '&') {
            StringBuilder temp = new StringBuilder();
            for (int j = i; j < text.length() && j < i + 7; ++j) {
                temp.append(text.charAt(j));
                Character c = entities.get(temp.toString());
                if (c != null) {
                    result.append(c);
                    i = j;
                    break;
                }
            }
            if (temp.charAt(temp.length() - 1) != ';') result.append(text.charAt(i));
        } else {
            result.append(text.charAt(i));
        }
    }
    return result.toString();
}

entityParser(text) {
    const entities = {
        "&quot;": '\"',
        "&apos;": '\'',
        "&amp;": '&',
        "&gt;": '>',
        "&lt;": '<',
        "&frasl;": '/'
    };

    let result = '';
    for (let i = 0; i < text.length; ++i) {
        if (text[i] === '&') {
            let temp = '';
            for (let j = i; j < text.length && j < i + 7; ++j) {
                temp += text[j];
                if (temp in entities) {
                    result += entities[temp];
                    i = j;
                    break;
                }
            }
            if (temp[temp.length - 1] !== ';') result += text[i];
        } else {
            result += text[i];
        }
    }
    return result;
}

