        graph.computeIfAbsent(edge[0], k -> new HashMap<>()).put(edge[1], 0);
        graph.computeIfAbsent(edge[1], k -> new HashMap<>()).put(edge[0], 0);
    }

    return dfs(n, 0, -1, hasApple, graph);
