    const count = new Array(n).fill(0);
    const MOD = 1000000007;

    for (const request of requests) {
        count[request[0]]++;
        if (request[1] + 1 < n) {
            count[request[1] + 1]--;
        }
    }
    for (let i = 1; i < n; i++) {
        count[i] += count[i - 1];
    }

    nums.sort((a, b) => a - b);
    count.sort((a, b) => a - b);

    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans = (ans + nums[i] * count[i]) % MOD;
    }

    return ans;
}

