import java.util.List;

public String reorderSpaces(String text) {
    int spaces = 0, words = 0;

    for (char c : text.toCharArray()) {
        if (c == ' ') spaces++;
    }

    String[] splitText = text.trim().split("\\s+");
    List<String> wordList = new ArrayList<>();
    for (String word : splitText) {
        wordList.add(word);
        words++;
    }

    int spacesBetweenWords = words == 1 ? 0 : spaces / (words - 1);
    int extraSpaces = words == 1 ? spaces : spaces % (words - 1);

    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words; i++) {
        result.append(wordList.get(i));
        if (i != words - 1) {
            result.append(" ".repeat(spacesBetweenWords));
        } else {
            result.append(" ".repeat(extraSpaces));
        }
    }

    return result.toString();
}

reorderSpaces(text) {
    const spaces = text.split(' ').length - 1;
    const words = text.trim().split(/\s+/);
    const numWords = words.length;

    const spacesBetweenWords = numWords === 1 ? 0 : Math.floor(spaces / (numWords - 1));
    const extraSpaces = spaces - spacesBetweenWords * (numWords - 1);

    return words.join(' '.repeat(spacesBetweenWords)) + ' '.repeat(extraSpaces);
}

