        let sub = s.slice(start, i);
        if (!seen.has(sub)) {
            seen.add(sub);
            let unique = maxUniqueSplit(s, i, seen);
            if (unique !== -1) {
                maxUnique = Math.max(maxUnique, unique + 1);
            }
            seen.delete(sub);
        }
    }
    return maxUnique;
}

