String findLexSmallestString(String s, int a, int b) {
    int n = s.length();
    String minStr = s;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 10; j++) {
            String rotatedStr = rotateString(s, b);
            String tempStr = addOdd(rotatedStr, a);
            minStr = minStr.compareTo(tempStr) < 0 ? minStr : tempStr;
            s = rotatedStr;
        }
        s = addAtIndex(s, a, n - i - 1);
    }
    return minStr;
}

private String rotateString(String s, int k) {
    k %= s.length();
    return s.substring(s.length() - k) + s.substring(0, s.length() - k);
}

private String addAtIndex(String s, int a, int index) {
    char[] arr = s.toCharArray();
    arr[index] = (char) ((arr[index] - '0' + a) % 10 + '0');
    return new String(arr);
}

private String addOdd(String s, int a) {
    StringBuilder sb = new StringBuilder(s);
    for (int i = 1; i < s.length(); i += 2) {
        sb.setCharAt(i, (char) ((s.charAt(i) - '0' + a) % 10 + '0'));
    }
    return sb.toString();
}

findLexSmallestString(s, a, b) {
    function rotate(s, k) {
        k %= s.length;
        return s.slice(s.length - k) + s.slice(0, s.length - k);
    }

    function addAtIndex(s, a, index) {
        const arr = [...s];
        arr[index] = (arr[index] - '0' + a) % 10 + '0';
        return arr.join('');
    }

    function addOdd(s, a) {
        return s.split('').map((ch, idx) => idx % 2 ? (parseInt(ch) + a) % 10 : ch).join('');
    }

    let smallest = s;
    for (let i = 0; i < s.length; i++) {
        for (let j = 0; j < 10; j++) {
            const rotated = rotate(s, b);
            const temp = addOdd(rotated, a);
            smallest = smallest < temp ? smallest : temp;
            s = rotated;
        }
        s = addAtIndex(s, a, s.length - i - 1);
    }
    return smallest;
}

findLexSmallestString(s: str, a: int, b: int) -> str:
    def add_odd(s: str, a: int) -> str:
        return ''.join([str((int(ch) + a) % 10) if idx % 2 else ch for idx, ch in enumerate(s)])

    def rotate(s: str, k: int) -> str:
        k %= len(s)
        return s[-k:] + s[:-k]

    smallest = s
    for _ in range(len(s)):
        for _ in range(10):
            rotated = rotate(s, b)
            temp = add_odd(rotated, a)
            smallest = min(smallest, temp)
            s = rotated
        s = add_odd(s, a)
    return smallest

