int numWays(String[] words, String target) {
    int n = words.length;
    int m = target.length();
    int[][] count = new int[n][26];
    int[][] dp = new int[m][n];
    final int mod = 1000000007;

    for (int i = 0; i < n; i++) {
        for (char c : words[i].toCharArray()) {
            count[i][c - 'a']++;
        }
    }

    for (int i = 0; i < n; i++) {
        dp[0][i] = count[i][target.charAt(0) - 'a'];
    }

    for (int i = 1; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                dp[i][j] = (dp[i][j] + (int)(((long) dp[i-1][k] * count[j][target.charAt(i) - 'a']) % mod)) % mod;
            }
        }
    }

    int res = 0;
    for (int i = 0; i < n; i++) {
        res = (res + dp[m-1][i]) % mod;
    }
    return res;
}

