    while (idx < n) {
        int curr_limit = maxWeight, prev_port = 0;
        for (int count = 0; count < maxBoxes && idx < n; ++idx) {
            if (boxes[idx][1] <= curr_limit) {
                if (prev_port != boxes[idx][0]) {
                    prev_port = boxes[idx][0];
                    ++trips;
                }
                curr_limit -= boxes[idx][1];
                ++count;
            }
        }
        ++trips;
    }
    return trips;
}

