class Solution {
    public int maxSumRangeQuery(int[] nums, int[][] requests) {
        int n = nums.length;
        int[] cnt = new int[n];
        int mod = (int) 1e9 + 7;

        for (int[] req : requests) {
            cnt[req[0]]++;
            if (req[1] + 1 < n) cnt[req[1] + 1]--;
        }

        for (int i = 1; i < n; i++) {
            cnt[i] += cnt[i - 1];
        }

        Arrays.sort(nums);
        Arrays.sort(cnt);

        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans += (long) nums[i] * cnt[i];
            ans %= mod;
        }

        return (int) ans;
    }
}

maxSumRangeQuery(nums, requests) {
    const n = nums.length;
    const cnt = new Array(n).fill(0);
    const mod = 1e9 + 7;

    for (const req of requests) {
        cnt[req[0]]++;
        if (req[1] + 1 < n) cnt[req[1] + 1]--;
    }

    for (let i = 1; i < n; i++) {
        cnt[i] += cnt[i - 1];
    }

    nums.sort((a, b) => a - b);
    cnt.sort((a, b) => a - b);

    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans += (BigInt(nums[i]) * BigInt(cnt[i])) % mod;
    }

    return Number(ans % mod);
}

