public class Solution {
    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        Map<Integer, List<int[]>> graph = new HashMap<>();

        for (int[] edge : edgeList) {
            graph.putIfAbsent(edge[0], new ArrayList<>());
            graph.putIfAbsent(edge[1], new ArrayList<>());
            graph.get(edge[0]).add(new int[]{edge[1], edge[2]});
            graph.get(edge[1]).add(new int[]{edge[0], edge[2]});
        }

        boolean[] answer = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int pj = queries[i][0], qj = queries[i][1], limitj = queries[i][2];

            Queue<int[]> q = new LinkedList<>();
            q.add(new int[]{pj, 0});
            boolean[] visited = new boolean[n];
            visited[pj] = true;

            while (!q.isEmpty()) {
                int[] curr = q.poll();

                for (int[] next : graph.getOrDefault(curr[0], new ArrayList<>())) {
                    if (curr[1] + next[1] < limitj) {
                        if (next[0] == qj) {
                            answer[i] = true;
                            break;
                        }
                        if (!visited[next[0]]) {
                            visited[next[0]] = true;
                            q.add(new int[]{next[0], curr[1] + next[1]});
                        }
                    }
                }
                if (answer[i]) 
                    break;
            }
        }
        return answer;
    }
}

distanceLimitedPathsExist(n, edgeList, queries) {
    const graph = new Map();

    for (const [u, v, dis] of edgeList) {
        if (!graph.has(u)) graph.set(u, []);
        if (!graph.has(v)) graph.set(v, []);
        graph.get(u).push([v, dis]);
        graph.get(v).push([u, dis]);
    }

    const answer = new Array(queries.length).fill(false);
    for (let i = 0; i < queries.length; i++) {
        const [pj, qj, limitj] = queries[i];

        const q = [[pj, 0]];
        const visited = new Array(n).fill(false);
        visited[pj] = true;

        while (q.length > 0) {
            const [curr_node, curr_dist] = q.shift();

            for (const [next_node, next_dist] of graph.get(curr_node) || []) {
                if (curr_dist + next_dist < limitj) {
                    if (next_node === qj) {
                        answer[i] = true;
                        break;
                    }
                    if (!visited[next_node]) {
                        visited[next_node] = true;
                        q.push([next_node, curr_dist + next_dist]);
                    }
                }
            }
            if (answer[i]) break;
        }
    }
    return answer;
}

collections import defaultdict, deque

def distanceLimitedPathsExist(n, edgeList, queries):
    graph = defaultdict(list)

    for u, v, dis in edgeList:
        graph[u].append((v, dis))
        graph[v].append((u, dis))

    answer = [False] * len(queries)
    for i, (pj, qj, limitj) in enumerate(queries):
        q = deque([(pj, 0)])
        visited = [False] * n
        visited[pj] = True

        while q:
            curr_node, curr_dist = q.popleft()

            for next_node, next_dist in graph[curr_node]:
                if curr_dist + next_dist < limitj:
                    if next_node == qj:
                        answer[i] = True
                        break
                    if not visited[next_node]:
                        visited[next_node] = True
                        q.append((next_node, curr_dist + next_dist))
            if answer[i]:
                break

    return answer

