maxNumEdgesToRemove(int n, vector<vector<int>>& edges) {
    vector<int> parent(2 * n + 1);
    iota(parent.begin(), parent.end(), 0);
    function<int(int)> find = [&](int x) { return x == parent[x] ? x : parent[x] = find(parent[x]); };
    auto unite = [&](int x, int y) { x = find(x); y = find(y); if (x != y) return parent[x] = y, true; return false; };
    sort(edges.begin(), edges.end(), greater<vector<int>>());
    int ans = 0, both = n - 1;
    for (auto &edge : edges) {
        int type, u, v; tie(type, u, v) = make_tuple(edge[0], edge[1], edge[2] + n);
        if (type == 3) if (unite(u, v)) --both;
        if (!both) break;
    }
    for (int type = 1; type < 3; ++type) {
        int ct = 0;
        for (auto &edge : edges) {
            int a, u, v; tie(a, u, v) = make_tuple(edge[0], edge[1], edge[2] + n);
            if (a == type) if (unite(u, v)) ++ct;
        }
        if (both + ct < n - 1) return -1;
        ans += ct;
    }
    return ans;
}

int maxNumEdgesToRemove(int n, int[][] edges) {
    int[] parent = new int[2 * n + 1];
    for (int i = 0; i <= 2 * n; ++i) parent[i] = i;
    int[] ct = new int[2], both = new int[]{n - 1};

    Arrays.sort(edges, (o1, o2) -> Integer.compare(o2[0], o1[0]));
    for (int[] edge : edges) {
        if (edge[0] == 3 && unite(parent, edge[1], edge[2] + n)) --both[0];
        if (both[0] == 0) break;
    }

    for (int type = 1; type < 3; ++type) {
        for (int[] edge : edges) {
            if (edge[0] == type && unite(parent, edge[1], edge[2] + n)) ++ct[type - 1];
        }
        if (both[type - 1] + ct[type - 1] < n - 1) return -1;
    }
    return ct[0] + ct[1] - n + 1;
}

private boolean unite(int[] parent, int u, int v) {
    u = find(parent, u);
    v = find(parent, v);
    if (u != v) {
        parent[u] = v;
        return true;
    }
    return false;
}

private int find(int[] parent, int u) {
    return parent[u] == u ? u : (parent[u] = find(parent, parent[u]));
}

