int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
    int[] pairMapping = new int[n];
    for (int[] pair : pairs) {
        pairMapping[pair[0]] = pair[1];
        pairMapping[pair[1]] = pair[0];
    }

    int unhappyCount = 0;
    for (int x = 0; x < n; x++) {
        int y = pairMapping[x];
        int[] prefX = preferences[x];
        int idxY = -1;
        for (int i = 0; i < prefX.length; i++) {
            if (prefX[i] == y) {
                idxY = i;
                break;
            }
        }

        for (int i = 0; i < idxY; i++) {
            int u = prefX[i];
            int v = pairMapping[u];
            int[] prefU = preferences[u];
            for (int j = 0; j < prefU.length; j++) {
                if (prefU[j] == x) {
                    unhappyCount++;
                    break;
                } else if (prefU[j] == v) {
                    break;
                }
            }
        }
    }

    return unhappyCount / 2;
}

