public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
    int[] serverRequests = new int[k];
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    Queue<Integer> availableServers = new LinkedList<>();

    for (int i = 0; i < k; i++) {
        availableServers.offer(i);
    }

    for (int i = 0; i < arrival.length; i++) {
        while (!pq.isEmpty() && pq.peek()[0] <= arrival[i]) {
            availableServers.offer(pq.poll()[1]);
        }

        if (!availableServers.isEmpty()) {
            int serverId = availableServers.poll();
            serverRequests[serverId]++;
            pq.offer(new int[]{arrival[i] + load[i], serverId});
        }
    }

    int maxRequests = 0;
    for (int requests : serverRequests) {
        maxRequests = Math.max(maxRequests, requests);
    }

    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < k; i++) {
        if (serverRequests[i] == maxRequests) {
            result.add(i);
        }
    }

    return result;
}

busiestServers(k, arrival, load) {
    const serverRequests = new Array(k).fill(0);
    const pq = [];
    const availableServers = Array.from({ length: k }, (_, i) => i);

    for (let i = 0; i < arrival.length; i++) {
        while (pq.length && pq[0][0] <= arrival[i]) {
            const [, serverId] = pq.shift();
            availableServers.push(serverId);
        }

        if (availableServers.length) {
            const serverId = availableServers.shift();
            serverRequests[serverId]++;
            pq.push([arrival[i] + load[i], serverId]);
            pq.sort((a, b) => a[0] - b[0]);
        }
    }

    const maxRequests = Math.max(...serverRequests);
    return serverRequests.reduce((result, requests, i) => {
        if (requests === maxRequests) {
            result.push(i);
        }
        return result;
    }, []);
}

