numberOfSets(int n, int k) {
    long long mod = 1e9 + 7;
    vector<vector<long long>> dp(n, vector<long long>(k + 1, 0));
    vector<long long> presum(n, 1);

    for (int j = 1; j <= k; ++j) {
        for (int i = 0; i < n; ++i) {
            dp[i][j] = presum[i];
            if (i) {
                dp[i][j] += dp[i - 1][j];
            }
            dp[i][j] %= mod;
            presum[i] = (presum[i] + dp[i][j - 1]) % mod;
        }
    }

    return dp[n - 1][k];
}

