        .map(point => Math.atan2(point[1] - location[1], point[0] - location[0]) * 180 / Math.PI)
        .sort((a, b) => a - b);
    angles.push(...angles.map(a => a + 360));
    let max_points = 0;
    let j = 0;
    const n = angles.length;
    for (let i = 0; i < 2 * n; i++) {
        while (angles[i] - angles[j] > angle) {
