int[] decode(int[] encoded) {
    int n = encoded.length + 1;
    int totalXor = 0;

    for (int i = 1; i <= n; i++) {
        totalXor ^= i;
    }

    int nonFirstXor = 0;
    for (int i = 1; i < n - 1; i += 2) {
        nonFirstXor ^= encoded[i];
    }

    int[] perm = new int[n];
    perm[0] = totalXor ^ nonFirstXor;

    for (int i = 1; i < n; i++) {
        perm[i] = perm[i - 1] ^ encoded[i - 1];
    }

    return perm;
}

