    function dfs(node, parent) {
        let depth = 0;
        for (const child of tree[node]) {
            if (child !== parent) depth = Math.max(depth, 1 + dfs(child, node));
        }
        return depth;
    }

    const ans = new Array(n - 1).fill(0);
    for (let i = 1; i <= n; i++) {
        const maxD = dfs(i, 0);
        if (maxD > 0) ans[maxD - 1]++;
    }
    return ans;
}

