private boolean dfs(int[] quantity, int[] counts, int idx) {
    if (idx == -1) {
        return true;
    }
    for (int i = 1; i <= 50; ++i) {
        if (counts[i] >= quantity[idx]) {
            counts[i] -= quantity[idx];
            if (dfs(quantity, counts, idx - 1)) {
                return true;
            }
            counts[i] += quantity[idx];
        }
    }
    return false;
}

