        }
        for (let i = 1; i <= 50; ++i) {
            if (counts[i] >= quantity[idx]) {
                counts[i] -= quantity[idx];
                if (dfs(idx + 1)) {
                    return true;
                }
                counts[i] += quantity[idx];
            }
        }
        return false;
