public int closestCost(int[] baseCosts, int[] toppingCosts, int target) {
    int closest = Integer.MAX_VALUE;
    Arrays.sort(toppingCosts);

    for (int base : baseCosts) {
        int diff = Math.abs(target - base);
        if (diff < closest) {
            closest = diff;
        }
        if (diff == 0) {
            return target;
        }
        for (int t0 = 0; t0 <= 2; t0++) {
            int x1 = base + t0 * toppingCosts[0];
            int diff1 = Math.abs(target - x1);
            if (diff1 < closest) {
                closest = diff1;
            }
            if (diff1 == 0) {
                return target;
            }
            for (int t1 = 0; t1 <= 2; t1++) {
                int x2 = x1 + t1 * toppingCosts[1];
                int diff2 = Math.abs(target - x2);
                if (diff2 < closest) {
                    closest = diff2;
                }
                if (diff2 == 0) {
                    return target;
                }
            }
        }
    }
    return target - closest;
}

closestCost(baseCosts, toppingCosts, target) {
    let closest = Infinity;

    function dfs(index, cost) {
        if (index === toppingCosts.length || cost >= target + closest) {
            closest = Math.min(closest, Math.abs(cost - target));
            return;
        }

        dfs(index + 1, cost);
        dfs(index + 1, cost + toppingCosts[index]);
        dfs(index + 1, cost + 2 * toppingCosts[index]);
    }

    for (const base of baseCosts) {
        dfs(0, base);
    }

    return target - (closest > target ? -closest : closest);
}

