java.util.PriorityQueue;

public int minimumDeviation(int[] nums) {
    PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
    int min_val = Integer.MAX_VALUE;

    for (int num : nums) {
        if (num % 2 == 0) {
            pq.offer(num);
        } else {
            pq.offer(num * 2);
        }
        min_val = Math.min(min_val, num);
    }

    int result = Integer.MAX_VALUE;
    while (true) {
        int top = pq.poll();
        result = Math.min(result, top - min_val);

        if (top % 2 == 1) break;
        pq.offer(top / 2);
        min_val = Math.min(min_val, top / 2);
    }
    return result;
}

minimumDeviation(nums) {
    const pq = new MaxPriorityQueue();
    let min_val = Infinity;

    for (const num of nums) {
        if (num % 2 === 0) {
            pq.enqueue(num);
        } else {
            pq.enqueue(num * 2);
        }
        min_val = Math.min(min_val, num);
    }

    let result = Infinity;
    while (true) {
        const top = pq.dequeue().element;
        result = Math.min(result, top - min_val);

        if (top % 2 === 1) break;
        pq.enqueue(Math.floor(top / 2));
        min_val = Math.min(min_val, Math.floor(top / 2));
    }
    return result;
}

