class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;

        Arrays.sort(nums);
        LinkedList<Integer> diffList = new LinkedList<>();
        for (int i = 0; i < k; ++i) {
            diffList.add(nums[(i + 1) * (n / k) - 1] - nums[i * (n / k)]);
        }

        int sum = 0;
        for (Integer diff : diffList) {
            sum += diff;
        }

        return sum;
    }
}

minimumIncompatibility(nums, k) {
    let n = nums.length;
    if (n % k !== 0) return -1;

    nums.sort((a, b) => a - b);
    let diffs = [];
    for (let i = 0; i < k; ++i) {
        diffs.push(nums[(i + 1) * (n / k) - 1] - nums[i * (n / k)]);
    }

    return diffs.reduce((acc, curr) => acc + curr, 0);
}

